import{z as s,x as o,o as B,c as d,q as l,j as r,D as A,d as a,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"消融设计的工程学","description":"","frontmatter":{"title":"消融设计的工程学","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rw-ablation-design.md","filePath":"llm/rw-ablation-design.md","lastUpdated":1791063341000}'),C={name:"llm/rw-ablation-design.md"};function D(F,E,p,m,c,h){const t=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=l('<h1 id="消融设计的工程学" tabindex="-1">消融设计的工程学 <a class="header-anchor" href="#消融设计的工程学" aria-label="Permalink to &quot;消融设计的工程学&quot;">​</a></h1><div class="epigraph"><p>比较的全部秘密在于：除了你在问的那个问题，其余一切保持相同。</p><footer>—— 据 Lucic 等, Are GANs Created Equal? A Large-Scale Study, ICML 2018 整理</footer></div><p><a href="/llm/rw-experiment-config">上一课</a>把跑变成账：单一配置入口、哈希贯穿三处、种子分立。有了账，才能做受控的比较。本课设计受控比较里最重要的一类——消融：回答「论文的结论靠哪个部件撑着」。注意方向：复现的消融不是重跑作者的消融表，而是从你自己的目标线倒推，问清哪些部件的差异足以解释对不上的数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>论文的消融表是作者的取舍留下的，不是为你的复现设计的：它常缺与基线同预算的对照，常只有单种子，常只消融作者自己认为创新的部分。直接照抄这份清单，会花算力回答别人的问题。复现要的回答是条件式的：如果方法复现对不上，差异最可能藏在哪个部件；如果结论线已对上，哪个部件的差异可以放过。缺口是把「部件贡献」从作者的叙述变成你自己账本上的受控实验。</p><p><span class="marginnote">「消融」（ablation）一词借自医学：切掉某个器官，看病人缺了什么功能，从而推断那个器官管什么。搬到模型上，就是删掉或替换某个部件，看指标掉多少，从而推断论文的结论靠不靠它撑着。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>消融从主张倒推。写出论文的核心主张 A，列出它依赖的部件集合：数据配比、损失项、架构改动、日程、稳定件。对每个嫌疑部件设计移除或替换实验，其余一切冻结——数据快照、预算、评测协议三件套冻结是底线。实验次序按信息量排：先动最可疑的部件，它的消融无论结果如何都压缩最多的假设空间；最不可能出问题的部件放最后，或者不跑。</p><p>对照必须同预算。参数匹配与计算匹配给出不同的答案：加一倍数据能赢的消融，赢的是预算不是设计。报告消融时写清匹配口径——同 FLOPs、同 token 数、还是同参数量。部件之间有交互时，逐个移除会低估冗余：两个部件互相补位，各删一个都看不出差别。此时用累积式设计——从裸基线起逐个加上部件，与逐个移除互为印证。</p><p><span class="marginnote">数字实例：同样是 10 亿参数的模型，一个训 1000 亿 token、一个训 2000 亿 token，后者计算量翻倍。若消融里「赢」的是训练更久的那版，你测到的是算力效应，不是设计差异——这就是必须写清匹配口径的原因。</span></p>',10)),(B(),r(n,null,{default:A(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E6%A0%B8%E5%BF%83%E4%B8%BB%E5%BC%A0%20A%22%5D%20--%3E%20PARTS%5B%22%E9%83%A8%E4%BB%B6%E6%B8%85%E5%8D%95%E4%B8%8E%E5%AB%8C%E7%96%91%E6%8E%92%E5%BA%8F%22%5D%0A%20%20PARTS%20--%3E%20AB1%5B%22%E7%A7%BB%E9%99%A4%E6%9C%80%E5%8F%AF%E7%96%91%E9%83%A8%E4%BB%B6%22%5D%0A%20%20PARTS%20--%3E%20AB2%5B%22%E6%9B%BF%E6%8D%A2%E6%AC%A1%E5%AB%8C%E7%96%91%E9%83%A8%E4%BB%B6%22%5D%0A%20%20AB1%20--%3E%20FREEZE%5B%22%E5%86%BB%E7%BB%93%EF%BC%9A%E6%95%B0%E6%8D%AE%2F%E9%A2%84%E7%AE%97%2F%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20AB2%20--%3E%20FREEZE%0A%20%20FREEZE%20--%3E%20READ%5B%22%E8%AF%BB%E6%95%B0%EF%BC%9A%E4%BF%A1%E5%8F%B7%E8%BF%98%E6%98%AF%E7%A7%8D%E5%AD%90%E5%99%AA%E5%A3%B0%22%5D%0A%20%20READ%20--%3E%7C%22%E5%88%86%E4%B8%8D%E6%B8%85%22%7C%20SEED%5B%22%E5%8A%A0%E7%A7%8D%E5%AD%90%E5%86%8D%E5%88%A4%22%5D%0A%20%20READ%20--%3E%7C%22%E7%BB%93%E8%AE%BA%E6%9B%B4%E6%96%B0%22%7C%20NEXT%5B%22%E6%9B%B4%E6%96%B0%E5%AF%B9%E7%85%A7%E9%9D%A2%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"为什么同预算对照是底线：训练结果对预算的敏感度常高于对设计的敏感度，预算不齐的消融测到的是预算效应。为什么单种子不够：上一课说过，0.3 分的差可能小于种子间方差；消融读到差异先查它是否超出你测过的噪声带，超出才叫信号。复现消融与论文消融冲突时的读法也不同：论文的消融支持「这个部件有贡献」，你的消融回答「这个部件的差异能否解释我对不上的部分」——前者是科学陈述，后者是归因证据，混用会把相关当因果。",-1)),(B(),r(n,null,{default:A(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%AE%8C%E6%95%B4%E6%96%B9%E6%B3%95%EF%BC%9A%E9%83%A8%E4%BB%B6%20A%20%E5%8A%A0%20B%22%5D%20--%3E%20R1%5B%22%E7%A7%BB%E9%99%A4%E5%BC%8F%EF%BC%9A%E5%8F%AA%E5%8E%BB%E6%8E%89%20A%22%5D%0A%20%20R1%20--%3E%20R2%5B%22B%20%E8%A1%A5%E4%BD%8D%EF%BC%8C%E8%AF%BB%E6%95%B0%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20R2%20--%3E%20R3%5B%22%E8%AF%AF%E5%88%A4%EF%BC%9AA%20%E6%B2%A1%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20F%20--%3E%20R4%5B%22%E7%A7%BB%E9%99%A4%E5%BC%8F%EF%BC%9A%E5%8F%AA%E5%8E%BB%E6%8E%89%20B%22%5D%0A%20%20R4%20--%3E%20R5%5B%22A%20%E8%A1%A5%E4%BD%8D%EF%BC%8C%E8%AF%BB%E6%95%B0%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20R5%20--%3E%20R6%5B%22%E8%AF%AF%E5%88%A4%EF%BC%9AB%20%E6%B2%A1%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20F%20--%3E%20C1%5B%22%E7%B4%AF%E7%A7%AF%E5%BC%8F%EF%BC%9A%E8%A3%B8%E5%9F%BA%E7%BA%BF%E5%85%88%E5%8A%A0%20A%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%8C%87%E6%A0%87%E4%B8%8A%E6%B6%A8%EF%BC%9AA%20%E6%9C%89%E8%B4%A1%E7%8C%AE%22%5D%0A%20%20C2%20--%3E%20C3%5B%22%E5%86%8D%E5%8A%A0%20B%EF%BC%9A%E4%B8%8D%E5%86%8D%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20C3%20--%3E%20C4%5B%22%E7%BB%93%E8%AE%BA%EF%BC%9AA%20%E8%B5%B7%E4%BD%9C%E7%94%A8%EF%BC%8CB%20%E4%B8%8E%20A%20%E5%86%97%E4%BD%99%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=l('<p><span class="marginnote">数字实例：同一配置跑三个种子得 42.1、42.4、42.7，最大跨度 0.6 分，这就是你的噪声带。此时单种子消融读到 0.3 分的下降，完全落在带内——先补种子再下结论，别急着宣布「部件有贡献」。</span></p><p><span class="marginnote">Musgrave 等 2020 的度量学习复查是个干净的标本：把基线训练与调参做到位后，多篇论文声称的损失函数优势缩到与种子噪声同量级。消融前先问基线的最好努力在哪，否则消融出来的「部件贡献」里混着基线的欠账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>消融不做无穷递归：停在能支撑目标线为止。结果复现通常不需要部件级消融——环境对齐后数字能对上，部件问题不存在；方法复现才需要关键消融，而且只做与目标线相关的子集。消融结果与论文冲突，不直接判「复现失败」：先回到坐标系检查（数据版本、评测协议），排除后再把冲突记档，交给下一课的归因次序处理。消融清单本身要进报告的决策表，注明每个实验的匹配口径与种子数——没有口径的消融数字与没有坐标系的分数一样，不可比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>消融从目标线倒推，不照抄论文的消融表；实验次序按信息量排。</li><li>三件套冻结：同数据快照、同预算、同评测协议；报告必须写清预算匹配口径。</li><li>单种子消融先过噪声带；部件有交互时用累积式与移除式互证。</li><li>复现消融回答「差异能否解释对不上」，与论文的「部件有贡献」是两种证据。</li><li>出处：Lucic 等, 2018；Musgrave 等, A Metric Learning Reality Check, ECCV 2020。</li></ul>',6))])}const f=s(C,[["render",D]]);export{_ as __pageData,f as default};
